import{_ as t,C as r,o,c as i,E as s,a2 as n}from"./chunks/framework.Cm6XCzck.js";const b=JSON.parse('{"title":"已安装，不等于已授权","description":"","frontmatter":{"title":"已安装，不等于已授权","date":"2026-09-02","column":"industry-architecture","category":"daily","article_type":"comparative-study","edition":"research-center","research_question":"企业智能体执行连接器调用前，必须绑定哪些权限身份与决策？","summary":"三份一手材料共同暴露一种治理错误：已安装或已启用状态无法证明谁在行动、目标允许什么、当前策略是否放行，也无法证明提供方接受了什么效果。","sources":["research/analysis/Q-20260902-02-connector-layered-authority.md"],"item_id":"Q-20260902-02","lifecycle":"Published","cover":"/assets/covers/daily-2026-09-02-installed-is-not-authorized-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/industry/2026-09-02-installed-is-not-authorized.md","filePath":"zh/industry/2026-09-02-installed-is-not-authorized.md","lastUpdated":1788361073000}'),l={name:"zh/industry/2026-09-02-installed-is-not-authorized.md"};function d(p,e,c,h,u,m){const a=r("ArticleCover");return o(),i("div",null,[s(a,{image:"/assets/covers/daily-2026-09-02-installed-is-not-authorized-cover.png",kicker:"行业架构 · 每日研究",title:"已安装，不等于已授权",summary:"三份一手材料共同暴露一种治理错误：已安装或已启用状态无法证明谁在行动、目标允许什么、当前策略是否放行，也无法证明提供方接受了什么效果。",version:"Q-20260902-02",status:"Daily Runtime V5 · 2026-09-02",languageHref:"/en/industry/2026-09-02-installed-is-not-authorized",languageLabel:"English"}),e[0]||(e[0]=n('<h1 id="已安装-不等于已授权" tabindex="-1">已安装，不等于已授权 <a class="header-anchor" href="#已安装-不等于已授权" aria-label="Permalink to &quot;已安装，不等于已授权&quot;">​</a></h1><p>一个企业智能体看到连接器标记为 <strong>已启用</strong>。应用几个月前获批，选中的账户昨天被切换，目标资源今天早上撤销了访问权。把可见标记直接当作执行权限，就是把多项持续变化的事实压缩成一个已经过期的答案。</p><p>安装状态说明某项能力可以被提供，却不能证明谁正在行动、当前选中哪个关联账户、提供方允许访问什么、运行时策略是否放行本次发生，也不能证明外部系统最终修改了什么。</p><p>三个一手样本分别揭示了这种区别。医疗集成文档把组织可用性与应用配置，同每位临床人员的登录、已批准范围和既有病历权限分开。另一份智能体身份文档记录了配置好的连接器权限，也记录了连接器策略与数据丢失防护在运行时的重新验证。固定版本的连接器源码则把选中的账户关联身份和工具信息送入应用工具策略判断。</p><p>它们不是同一种协议。比较的价值更窄：<strong>连接器权限是分层的，已安装或已启用标记不能替代调用时授权。</strong></p><h2 id="可用性和授权回答不同的问题" tabindex="-1">可用性和授权回答不同的问题 <a class="header-anchor" href="#可用性和授权回答不同的问题" aria-label="Permalink to &quot;可用性和授权回答不同的问题&quot;">​</a></h2><p>管理可用性回答组织是否提供连接器。配置能力回答智能体能够尝试调用哪些工具或范围。两者都是前提，却都没有识别某次调用中的实际行动主体。</p><p>医疗集成文档把边界写得很具体。工作区与应用设置不会扩大临床人员既有的病历权限。用户仍需登录，批准范围仍有边界，目标系统继续执行自己的访问规则。因此，连接器可以被正确安装，而特定人员仍无权访问特定记录。</p><p>另一份智能体身份文档揭示了另一层分离。连接器接口权限可以配置在持久的智能体身份上，而连接器运行时、高级连接器策略与数据丢失防护控制仍会重新判断路径。持久配置描述能力；当前策略决定这一次是否可以执行。</p><h2 id="账户关联是授权主张的一部分" tabindex="-1">账户关联是授权主张的一部分 <a class="header-anchor" href="#账户关联是授权主张的一部分" aria-label="Permalink to &quot;账户关联是授权主张的一部分&quot;">​</a></h2><p>连接器名称不是行动身份。同一个连接器可能对应多个关联账户、租户或认证上下文。如果所选账户会变化，只记住“用户批准过这个连接器”就过于粗糙。</p><p>引用的固定版本源码把选中的账户关联身份、工具身份与注解送入应用工具策略判断。这是针对一个版本的实现证据，并非通用架构证明；但它说明了正确的问题：授权属于特定关联关系下的一次具体工具调用，而不属于抽象连接器标签。</p><p>记忆中的批准至少应绑定连接器、工具、账户关联、目标范围和相关发生条件。切换账户、改变工具、扩大目标或撤销权限，都应使受影响的关系失效，而不是假装安装事实本身改变了。</p><h2 id="六层构成有边界的权限链" tabindex="-1">六层构成有边界的权限链 <a class="header-anchor" href="#六层构成有边界的权限链" aria-label="Permalink to &quot;六层构成有边界的权限链&quot;">​</a></h2><p>受治理的连接器调用至少需要六项可分别检查的主张。</p><p>第一，管理可用性：环境是否提供连接器。第二，配置能力：智能体配置是否允许该工具或范围。第三，行动主体或账户关联：提供方将识别哪个身份。第四，目标资源权限：该身份此刻能否作用于该对象。第五，运行时策略：当前发生是否满足组织与任务约束。第六，提供方效果证据：外部系统接受或改变了什么。</p><p>前两层描述可用能力；中间三层决定此刻是否授权这次尝试；最后一层记录结果。任何一层都不能安全推出另一层。</p><p>这种分离也明确了事实所有者。管理员管理可用性，智能体配置管理暴露能力，身份系统建立行动者，提供方拥有目标权限，运行时策略评估当前条件，提供方回执或对账状态证明外部效果。</p><h2 id="授权决定不是效果回执" tabindex="-1">授权决定不是效果回执 <a class="header-anchor" href="#授权决定不是效果回执" aria-label="Permalink to &quot;授权决定不是效果回执&quot;">​</a></h2><p>调用前的判断可以授权一次尝试，却不能证明提供方已经接受。客户端看似成功的响应可能丢失、重试，或者无法明确对应某项外部更改。反过来，提供方拒绝也不等于本地策略判断错误。</p><p>对于有后果的行动，应把准入决定与外部效果记录保存为两类证据。响应丢失时，应查询提供方状态，或在提供方支持时使用幂等机制。仅因本地日志缺少成功标记就重放调用，可能复制已经发生的效果。</p><p>引用来源没有证明恰好一次执行、不可变审计历史或共享回执格式。这些仍是设计要求，而不是来源支持的产品事实。</p><h2 id="单一状态仍然可以存在" tabindex="-1">单一状态仍然可以存在 <a class="header-anchor" href="#单一状态仍然可以存在" aria-label="Permalink to &quot;单一状态仍然可以存在&quot;">​</a></h2><p>运维界面需要简洁。只要明确它总结的是可用性，而不是授予无限执行权，一个“已启用”标记仍然有用。</p><p>危险发生在系统简化展示时也丢掉底层分层。可靠的运行时可以展示一个状态，同时保存每项事实、时效和责任主体。必要层缺失或过期时，应闭合失败，并解释无法建立哪项主张。</p><p>撤销语义也会更精确。目标权限撤销只使目标授权失效；账户切换只使行动者绑定失效；策略变化只使本次发生的决定失效。它们都不改变“连接器曾被安装”这一历史事实。</p><h2 id="比较边界必须严格" tabindex="-1">比较边界必须严格 <a class="header-anchor" href="#比较边界必须严格" aria-label="Permalink to &quot;比较边界必须严格&quot;">​</a></h2><p>这些样本采用不同架构、术语与执行点。官方文档描述预期行为，不是独立复现；源码样本只证明固定版本向一次策略判断传递了哪些信息。</p><p>现有证据没有证明通用连接器授权协议、凭据隔离、恰好一次效果或统一撤销语义。它支持的结论更窄：管理启用、配置能力、行动身份、目标权限、运行时策略与提供方效果必须保持为不同主张。</p><p>仍待解决的问题包括：怎样设计不泄露凭据的可移植权限回执；运行时如何表示它能查询但不能控制的提供方权限；哪些变化必须要求显式重新批准；以及连接器响应丢失时如何对账外部效果。</p><p><strong>来源：</strong> <a href="https://help.openai.com/articles/20001490-using-the-epic-plugin-with-chatgpt-and-codex" target="_blank" rel="noreferrer">医疗插件文档</a>、<a href="https://openai.com/index/chatgpt-connects-health-records-and-healthcare-sources/" target="_blank" rel="noreferrer">医疗集成说明</a>、<a href="https://learn.microsoft.com/en-us/microsoft-copilot-studio/admin-use-entra-agent-identities" target="_blank" rel="noreferrer">智能体身份连接器文档</a>，以及<a href="https://github.com/openai/codex/blob/eb10d91e48ccbd0930427461fb392337addb1ac0/codex-rs/core/src/mcp_tool_call.rs" target="_blank" rel="noreferrer">引用版本的连接器源码</a></p>',31))])}const f=t(l,[["render",d]]);export{b as __pageData,f as default};
